let resp = $node["HTTP Request"].json;

if (Array.isArray(resp)) {
  resp = resp[0];
}

if (!resp.choices) {
  throw new Error("Could not find resp.choices – check the structure with console.log(resp)");
}

const content = resp.choices[0]?.message?.content;
if (!content) {
  throw new Error("Could not find message.content");
}

// Remove ``` fences
let jsonText = content
  .replace(/^```.*\n/, "")
  .replace(/```$/, "")
  .trim();

// Try parsing directly first
let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (_) {
  // Try extracting array OR object
  const match = jsonText.match(/(\[.*\]|\{.*\})/s);
  if (!match) {
    throw new Error("Could not find JSON object or array");
  }
  parsed = JSON.parse(match[0]);
}

// Ensure output is always an array
let stocks = Array.isArray(parsed) ? parsed : [parsed];

// Map to n8n items
return stocks.map(stock => ({
  json: {
    stockName:           stock["Stock Name"],
    nseCode:             stock["NSE Code"],
    sentiment:           stock["Positive/Negative"],
    description:         stock["Description"],
    analysisOfImpact:    stock["Analysis of Likely Impact"],
    confidence:          stock["Confidence Level"],
    likelyImpactPercent: stock["Likely Impact on Stock Today"],
    date:                stock["Date"]
  }
}));

// 1. Grab the output of your HTTP Request node by name:
let resp = $node["Basic LLM Chain"].json;

// 2. If it's an array (i.e. you did NOT split into items), take the first element:
if (Array.isArray(resp)) {
  resp = resp[0];
}

// 3. Check if response has the expected structure
if (!resp || typeof resp !== 'object') {
  throw new Error("Response is not a valid object – check the structure");
}

// 4. Extract the text content from the first element
let content;
if (resp.text) {
  content = resp.text;
} else if (resp.choices) {
  // Fallback to old format if needed
  content = resp.choices[0]?.message?.content;
}

if (!content) {
  throw new Error("Could not find text content in response");
}

// 5. Strip any ``` fences
let jsonText = content
  .replace(/^```json\n/, "")
  .replace(/^```.*\n/, "")
  .replace(/\n```[\s\S]*$/, "")  // Remove closing ``` and everything after it
  .trim();

// 6. Extract JSON array between [ ... ]
const match = jsonText.match(/\[[\s\S]*\]/);
if (!match) {
  throw new Error("Could not find JSON array in the response");
}
jsonText = match[0]; // the actual JSON array

// 7. Parse the JSON array
let stocks;
try {
  stocks = JSON.parse(jsonText);
} catch (err) {
  throw new Error("Invalid JSON: " + err.message + "\nRaw text:\n" + jsonText);
}

// 8. Output one item per stock for Google Sheets
return stocks.map(stock => ({
  json: {
    stockName:           stock["Stock Name"],
    nseCode:             stock["NSE Code"],
    sentiment:           stock["Positive/Negative"],
    description:         stock["Description"],
    analysisOfImpact:    stock["Analysis of Likely Impact"],
    confidence:          stock["Confidence Level"],
    likelyImpactPercent: stock["Likely Impact on Stock Today"],
    date:                stock["Date"]
  }
}));

